export default "// DOM-only rendering: provider and finding text is never inserted as HTML.\nconst $=id=>document.getElementById(id);\nconst fmt=value=>value?new Date(Number(value)).toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'—';\nconst node=(tag,cls,text)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(text!==undefined)el.textContent=String(text);return el;};\nconst clear=el=>{while(el.firstChild)el.firstChild.remove();};\nconst empty=(el,message)=>el.append(node('div','empty',message));\nconst dayNY=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/New_York',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());\nfunction findingCard(f) {\n  const evidence=f.evidence || {}, card=node('article','finding'),row=node('div','row'),left=node('div');\n  left.append(node('div','title',`${f.game_key} · ${String(f.reason_code || '').replaceAll('_',' ')}`));\n  left.append(node('div','sub',`${f.status || 'recorded'} · First seen ${fmt(f.first_seen)} · Last seen ${fmt(f.last_seen)} · ${f.failure_layer || 'unknown layer'}`));\n  row.append(left,node('span',`badge ${f.severity || 'medium'}`,String(f.severity || 'medium').toUpperCase()));card.append(row);\n  card.append(node('div','detail',evidence.detail || 'Review the recorded evidence.'));\n  card.append(node('div','evidence',`Observed: ${JSON.stringify(evidence.observed ?? {})} · Expected: ${evidence.expected || 'review'} · Confidence: ${Math.round(Number(f.confidence || 0)*100)}%`));\n  return card;\n}\nfunction gameCard(g,findings) {\n  const e=g.latestEvidence || {},s=e.state || {},teams=(s.teams || []).map(t=>t?.[0] || '?').join(' vs '),\n    associated=findings.filter(f=>f.game_key===g.game_key || f.evidence?.affectedGames?.includes(g.game_key));\n  const card=node('article','game'),row=node('div','row'),left=node('div');\n  left.append(node('div','title',teams || g.game_key));\n  left.append(node('div','sub',`${g.sport} · ${g.observations} observations · ${fmt(g.first_seen)} to ${fmt(g.last_seen)}`));\n  row.append(left,node('span',associated.length?'badge medium':'badge',associated.length?`${associated.length} finding${associated.length===1?'':'s'}`:'No findings'));\n  card.append(row,node('div','detail',`Rating range ${g.min_rating}–${g.peak_rating} · Latest recorded ${s.score ?? '—'} · ${(s.teams || []).map(t=>t?.[2] ?? '—').join('–')}`));\n  if(g.legacy_unavailable_rating_rows>0)card.append(node('div','evidence',`${g.legacy_unavailable_rating_rows} legacy unavailable rating row(s) excluded from this range; original row values remain retained.`));\n  if(associated.length)card.append(node('div','evidence',associated.map(f=>String(f.reason_code || '').replaceAll('_',' ')).join(' · ')));\n  return card;\n}\nasync function refresh() {\n  try {\n    const day=$('day').value || dayNY(),res=await fetch(`/report?date=${encodeURIComponent(day)}`,{credentials:'same-origin',cache:'no-store'});\n    if(res.status===401){location.href='/dashboard';return}if(!res.ok)throw new Error(`Report HTTP ${res.status}`);\n    const data=await res.json(),run=data.latestRun || {},post=data.postSlate || {},all=post.findings || [],active=data.activeUnresolvedFindings || [];\n    const history=(post.events || []).map(event=>({game_key:event.game_key,reason_code:event.reason_code,\n      status:event.event,first_seen:event.at,last_seen:event.at,severity:event.evidence?.severity || 'medium',\n      failure_layer:event.evidence?.failureLayer || 'unknown',confidence:event.evidence?.confidence || 0,\n      evidence:event.evidence}));\n    const byReason=new Map();for(const f of [...all,...history])byReason.set(`${f.game_key}|${f.reason_code}`,f);\n    const healthy=Boolean(run.finished_at && !run.error && Date.now()-run.finished_at<8*60000);\n    $('status-dot').classList.toggle('warn',!healthy);\n    $('status').textContent=run.error?'Audit scan failed':healthy?'Monitoring active':'Waiting for scheduled scan';\n    $('updated').textContent=`Last successful audit ${fmt(data.lastSuccessfulScan)} · Feed age ${data.sourceFreshnessMs==null?'—':Math.round(data.sourceFreshnessMs/60000)+' min'}`;\n    $('games-checked').textContent=run.games_checked ?? '—';$('checks-completed').textContent=run.checks_completed ?? '—';\n    $('clean-games').textContent=run.clean_games ?? '—';$('active-findings').textContent=data.activeUnresolvedCount ?? 0;\n    clear($('findings'));if(active.length)active.forEach(f=>$('findings').append(findingCard(f)));else empty($('findings'),'No active anomalies.');\n    $('night-summary').textContent=`${post.distinctGames || 0} distinct games · ${post.scans || 0} scheduled scans · ${post.checksCompleted ?? 'unavailable'} checks · ${history.filter(f=>f.status==='opened').length} findings opened`;\n    clear($('games'));if(post.gameSummaries?.length)post.gameSummaries.forEach(g=>$('games').append(gameCard(g,[...byReason.values()])));else empty($('games'),'No live games have been audited on this night yet. Inactive slates are skipped.');\n    clear($('history'));if(history.length)history.forEach(f=>$('history').append(findingCard(f)));else empty($('history'),'No confirmed finding events recorded on this night.');\n  } catch(error){$('status-dot').classList.add('warn');$('status').textContent='Dashboard data unavailable';$('updated').textContent=String(error)}\n}\nasync function init(){\n  try{const response=await fetch('/export/dates',{credentials:'same-origin',cache:'no-store'});\n    if(response.ok){const dates=await response.json();$('day').value=dates.defaultDate || dayNY();}\n    else $('day').value=dayNY();\n  }catch{$('day').value=dayNY()}\n  await refresh();\n}\nconst valueText=value=>value===null||value===undefined?'unavailable':typeof value==='object'?JSON.stringify(value):String(value);\nconst label=value=>String(value||'insufficient evidence').replaceAll('_',' ');\nconst trajectoryId=(key,model)=>'trajectory-'+encodeURIComponent(key+'|'+model);\nfunction evidenceDetails(title,value){\n  const detail=node('details');detail.append(node('summary',null,title),node('pre','evidence',JSON.stringify(value,null,2)));return detail;\n}\nfunction observationLink(key,model,text='Supporting observations'){\n  const link=node('a','evidence-link',text);link.href='#'+trajectoryId(key,model);return link;\n}\nfunction qualityCard(r){\n  const card=node('article','finding');\n  if(r.priority)card.append(node('span',`badge ${['critical','high','medium','low'].includes(r.priority)?r.priority:'low'}`,`${String(r.priority).toUpperCase()} PRIORITY`));\n  card.append(node('div','title',`${r.matchup||r.gameKey} \\u00b7 rating ${r.rating??'unavailable'} \\u00b7 ${(r.scores||[]).join('-')}`));\n  card.append(node('div','sub',`${r.gameKey} \\u00b7 ${fmt(r.observedAt)} \\u00b7 period ${r.period??'?'}, ${r.clockSeconds??'?'}s \\u00b7 ${r.modelVersion}`));\n  card.append(node('div','detail',`${label(r.classification)} \\u00b7 ${r.confidence||'unknown'} confidence. ${r.suspectedCause||r.whyInvestigate||r.reason||''}`));\n  card.append(node('div','evidence',`Evidence: ${(r.signals||[]).join('; ')||valueText(r.verifiedSituation??r.situation)}. Missing: ${(r.missingEvidence||r.evidenceGaps||[]).join('; ')||'none identified'}.`));\n  if(r.sourceEvent)card.append(node('div','evidence',`Source event ${r.sourceEvent.id} \\u00b7 event time ${fmt(r.sourceEvent.occurredAt)} \\u00b7 ${r.sourceEvent.text||''}`));\n  card.append(node('div','detail',`Next: ${r.recommendedCorrection||r.proposedInvestigation||r.proposedCorrection||'Replay matched states before changing scoring.'}`));\n  card.append(observationLink(r.gameKey,r.modelVersion),evidenceDetails('Investigation evidence and regression risks',r));\n  return card;\n}\nfunction qualitySection(parent,id,title){\n  const section=node('section','quality-section');section.id=id;section.append(node('h3',null,title));parent.append(section);return section;\n}\nfunction renderQuality(q,el,date){\n  const games=q.games||[],recommendations=q.recommendations||[];\n  const navigation=node('nav','quality-nav');navigation.ariaLabel='Scoring quality sections';\n  for(const [id,title] of [['quality-summary','Summary'],['quality-priority','Concerns'],['quality-events','Events'],['quality-alerts','Alert usefulness'],['quality-calibration','Calibration'],['quality-evidence','Evidence'],['quality-recommendations','Investigations']]){\n    const link=node('a',null,title);link.href='#'+id;navigation.append(link);\n  }\n  el.append(navigation);\n  const overview=qualitySection(el,'quality-summary','Executive summary');\n  overview.append(node('p','detail',`${games.length} game/model trajectories; ${(q.modelCohorts||[]).length} separate model cohorts. ${(q.confirmedScoringDefects||[]).length} confirmed scoring defects; ${(q.topOverrated||[]).length} overrating reviews and ${(q.topUnderrated||[]).length} underrating reviews.`));\n  overview.append(node('p','evidence','A concern is an investigation, not a scoring change. Completed ratings, live peaks and current watchability have different meanings. One slate cannot establish sport calibration.'));\n  if(q.executiveSummary)overview.append(evidenceDetails('Summary evidence',q.executiveSummary));\n  const integrity=qualitySection(el,'quality-integrity','Confirmed integrity problems');\n  if(!(q.integrityProblems||[]).length)empty(integrity,'No deterministic failures in the analyzed observations.');\n  for(const f of q.integrityProblems||[]){const card=node('article','finding');card.append(node('div','title',`${f.gameKey} \\u00b7 ${fmt(f.observedAt)}`),node('div','detail',valueText(f.codes||f.detail)),evidenceDetails('Integrity evidence',f));integrity.append(card);}\n  if(q.historicalFindingReview?.length){\n    const history=qualitySection(el,'quality-historical-review','Historical findings reconsidered');\n    history.append(node('p','evidence','Original findings remain in the export. These are updated interpretations, not changes to historical records.'));\n    for(const r of q.historicalFindingReview){const card=node('article','finding');card.append(node('div','title',`${r.gameKey} \\u00b7 ${r.reasonCode}`),node('div','detail',`${label(r.classification)}. ${r.reason||r.detail||''}`),evidenceDetails('Supporting evidence',r));history.append(card);}\n  }\n  const priorities=qualitySection(el,'quality-priority','High-priority scoring-quality concerns');\n  const concerns=recommendations.filter(r=>['confirmed_defect','strong_calibration_concern','calibration_hypothesis'].includes(r.classification));\n  const priority=concerns.filter(r=>['critical','high'].includes(r.priority));\n  if(priority.length)priority.slice(0,10).forEach(r=>priorities.append(qualityCard(r)));else empty(priorities,'No critical/high-priority scoring concerns in retained evidence. Other investigations and evidence gaps remain below.');\n  if(concerns.length>priority.length)priorities.append(node('p','evidence',`${concerns.length-priority.length} additional scoring concerns have medium/low or unassigned priority and remain in Recommended investigations.`));\n  for(const [id,title,items] of [['quality-over','Potentially overrated games',q.topOverrated||[]],['quality-under','Potentially underrated games',q.topUnderrated||[]]]){\n    const section=qualitySection(el,id,title);if(items.length)items.forEach(r=>section.append(qualityCard(r)));else empty(section,'No supported candidates; coverage may be incomplete.');\n  }\n  const eventSection=qualitySection(el,'quality-events','Significant events and rating responses');\n  const eventPriority=e=>Number.isFinite(e.eventTimestamp??e.event?.occurredAt)?Number.isFinite(e.change??e.delta??e.ratingChange)?0:1:2;\n  const responses=games.flatMap(g=>(g.eventResponses||[]).map(e=>({...e,gameKey:g.gameKey,modelVersion:g.modelVersion,matchup:g.matchup}))).sort((a,b)=>eventPriority(a)-eventPriority(b));\n  eventSection.append(node('p','evidence','Observed response intervals are associations. Provider publication latency, polling delay and scoring behavior stay separate; unavailable timestamps remain unavailable.'));\n  if(!responses.length)empty(eventSection,'No usable event-response measurements in retained data.');\n  for(const e of responses.slice(0,40)){\n    const card=node('article','game');card.append(node('div','title',e.matchup||e.gameKey),node('div','detail',`${e.event?.text||e.event?.type||e.eventType||e.event?.id||'State transition'}: ${valueText(e.beforeRating??e.ratingBefore??e.baseline)} to ${valueText(e.afterRating??e.ratingAfter??e.rating)}; change ${valueText(e.change??e.delta??e.ratingChange)}.`),node('div','evidence',`${e.event?.retrospective?'Retrospective later-cache association; historical availability unknown. ':''}${label(e.status)}. Direction: ${valueText(e.directionAssessment??{expected:e.expectedDirection,consistent:e.directionConsistent,magnitude:e.magnitudeAssessment})}.`),observationLink(e.gameKey,e.modelVersion),evidenceDetails('Timing, uncertainty and concurrent events',e));eventSection.append(card);\n  }\n  if(responses.length>40)eventSection.append(node('p','evidence',`Showing 40 of ${responses.length} responses. Full details remain in the ZIP export and game trajectories.`));\n  const volatility=qualitySection(el,'quality-volatility','Rating volatility and discontinuities');\n  const moves=games.filter(g=>g.volatility?.majorChanges?.length);\n  if(!moves.length)empty(volatility,'No major changes supported by comparable retained observations.');\n  for(const g of moves){const card=node('article','game');card.append(node('div','title',`${g.matchup||g.gameKey} \\u00b7 ${g.modelVersion}`),node('div','detail',`Maximum observed change ${g.volatility.maxAbsoluteChange}; ${g.volatility.majorChanges.length} major changes.`),observationLink(g.gameKey,g.modelVersion),evidenceDetails('Component changes and comeback evidence',{volatility:g.volatility,comebackAnalysis:g.comebackAnalysis}));volatility.append(card);}\n  const alerts=qualitySection(el,'quality-alerts','Alert usefulness');\n  alerts.append(node('p','evidence','First observed crossings can be later than the true crossing. Remaining game time is not wall-clock viewing time. Episodes and sampled duration exclude uncertain gaps. Notification behavior is unchanged.'));\n  if(!games.some(g=>g.thresholds?.length))empty(alerts,'Threshold trajectories are unavailable.');\n  for(const g of games.filter(g=>g.thresholds?.length)){\n    const t=g.thresholds.find(t=>t.threshold===85),card=node('article','game');\n    card.append(node('div','title',`${g.matchup||g.gameKey} \\u00b7 ${g.modelVersion}`),node('div','detail',t?.firstObservedAt?`First observed 85+: ${fmt(t.firstObservedAt)}; game time remaining ${valueText(t.gameTimeRemainingSeconds)} seconds; ${t.episodeCount} episode(s).`:'No 85+ crossing observed in this cohort.'),node('div','evidence',`Usefulness: ${valueText(t?.firstCrossingUsefulness)}. Sampled time 85+: ${valueText(t?.estimatedSecondsAbove)} seconds.`),observationLink(g.gameKey,g.modelVersion),evidenceDetails('70 / 80 / 85 / 90 / 95 crossings and uncertainty',g.thresholds));alerts.append(card);\n  }\n  const calibration=qualitySection(el,'quality-calibration','Sport-specific calibration and model-version comparisons');\n  calibration.append(node('p','evidence','Each model version has its own denominator and distribution. Different cohorts are observational, not a controlled release comparison. Soccer is hidden; tennis calibration is limited to verified Grand Slams.'));\n  for(const cohort of q.modelCohorts||[]){\n    calibration.append(node('h4',null,`Calibration \\u00b7 ${cohort.modelVersion}`));\n    for(const s of cohort.sports||[]){\n      if(s.sport==='Soccer')continue;\n      const card=node('article','game');card.append(node('div','title',s.displaySport||(s.sport==='NCAAB'?'NCAAM':s.sport)));\n      card.append(node('div','detail',`${s.gamesWithRating??0} games with ratings \\u00b7 reaching 70/80/85/90/95: ${Object.values(s.percentageReaching||{}).map(v=>v===null?'unknown':Number(v).toFixed(1)+'%').join(' / ')} \\u00b7 peak median ${s.peakDistribution?.median??'unknown'} \\u00b7 seconds >85: ${s.estimatedSecondsAbove85??'unknown'}`));\n      card.append(node('div','evidence',`${(s.significantNeverReached85||[]).length} significant games never observed at 85. ${s.comparability85||'Equivalence across sports is unvalidated.'}`),evidenceDetails('Calibration evidence and limitations',s));calibration.append(card);\n    }\n  }\n  if(!(q.modelCohorts||[]).length)empty(calibration,'No retained live observations. All sport calibration metrics are unavailable.');\n  const evidence=qualitySection(el,'quality-evidence','Evidence coverage and limitations');\n  const coverage=q.evidenceCoverage||{};\n  evidence.append(node('p','detail',`Usable scoring observations: ${valueText(coverage.usableScoringObservations)} / ${valueText(coverage.totalObservations)}. Complete score-progression evidence: ${valueText(coverage.completeScoreProgressionObservations)}. Complete contextual observations: ${valueText(coverage.completeContextualObservations)}.`));\n  evidence.append(node('p','evidence','Complete contextual evidence requires the stricter situation, market and team-quality fields. A partial context record can still have a usable rating and score progression. Lightweight trajectory completeness and flagged diagnostic detail are separate export coverage measures. Refresh start and acquisition timestamps do not establish provider publication latency.'),evidenceDetails('Contextual and usable evidence counts',coverage),evidenceDetails('Missing evidence by game and model',q.missingEvidence||[]));\n  const retrospectiveResponses=responses.filter(e=>e.event?.retrospective);\n  evidence.append(node('p','evidence',`Retrospective event associations: ${retrospectiveResponses.length}; with provider event wallclock: ${retrospectiveResponses.filter(e=>Number.isFinite(e.eventTimestamp??e.event?.occurredAt)).length}. Missing-timestamp counts describe original historical observations. Later-cache events are separate evidence and never backfill those observations.`));\n  const investigation=qualitySection(el,'quality-recommendations','Recommended investigations');\n  for(const f of q.qualitativeFindings||[])investigation.append(evidenceDetails(`${f.gameKey} · ${f.reasonCode} · ${f.classification}`,f));\n  if(!recommendations.length)empty(investigation,'Additional event and scoring-component evidence is required before a supported scoring change can be recommended.');\n  for(const r of recommendations)investigation.append(qualityCard(r));\n  const trajectories=qualitySection(el,'quality-trajectories','Supporting game observations');\n  trajectories.append(node('p','evidence','Each identifier maps to retained observations in findings.json. The dashboard previews up to 80 trajectory points per game/model; the export contains every retained point within the reported read limits.'));\n  for(const g of games){\n    const details=node('details','game');details.id=trajectoryId(g.gameKey,g.modelVersion);\n    details.append(node('summary',null,`${g.matchup||g.gameKey} \\u00b7 ${g.modelVersion}`),node('p','evidence',g.gameKey),node('pre','evidence',JSON.stringify({ratingContexts:g.ratingContexts,trajectory:(g.ratingTrajectory||[]).slice(0,80),watchability:g.watchability,comebackAnalysis:g.comebackAnalysis,eventResponses:g.eventResponses},null,2)));trajectories.append(details);\n  }\n  evidence.append(evidenceDetails('Methodology and analysis limits',{methodology:q.methodology,limitations:q.limitations,simultaneousPriorityConflicts:q.simultaneousPriorityConflicts}));\n}\nlet qualityGeneration=0;\nfunction invalidateQuality(){qualityGeneration++;clear($('quality'));$('quality-status').textContent='Load quality for the selected date.';}\nasync function loadQuality(){\n  const generation=++qualityGeneration,date=$('day').value||dayNY();\n  $('quality-load').disabled=true;$('quality-status').textContent='Analyzing retained live observations…';\n  try{\n    const response=await fetch(`/quality?date=${encodeURIComponent(date)}`,{credentials:'same-origin',cache:'no-store'});\n    if(response.status===401){location.href='/dashboard';return}if(!response.ok)throw Error(`Quality HTTP ${response.status}`);\n    const data=await response.json();if(generation!==qualityGeneration)return;\n    const q=data.scoringQuality,el=$('quality');clear(el);\n    $('quality-status').textContent=`${data.dateNewYork} · ${q.modelCohorts.length} scoring model(s). Hypotheses require review; an equivalent 85 across sports is not established. Duration is a sampled estimate. Missing evidence is not uneventful play.`;\n    renderQuality(q,el,date);\n  }catch(error){if(generation===qualityGeneration)$('quality-status').textContent=String(error);}\n  finally{$('quality-load').disabled=false;}\n}\n$('quality-load').addEventListener('click',loadQuality);\n$('refresh').addEventListener('click',refresh);$('day').addEventListener('change',()=>{invalidateQuality();refresh();});\n$('export').addEventListener('click',()=>{const date=$('day').value || dayNY();location.href=`/export?date=${encodeURIComponent(date)}`});\ninit();setInterval(refresh,60000);\n";
